# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List

from rosterkit.models import Student

# ---
def contact_rows(students: List[Student]) -> List[str]:
    """Name, section and email rows, sorted by name."""
    if not students:
        raise ValueError("contact sheet needs students")
    for student in students:
        if not student.email:
            raise ValueError(
                f"no email for {student.display_name}"
                f" (id {student.student_id})"
            )
    ordered = sorted(
        students, key=lambda student: student.display_name
    )
    return [
        f"{student.display_name:<20} "
        f"{student.section:<8} {student.email}"
        for student in ordered
    ]
